ddl.statement:
alter table public.client_settings
  add column if not exists reversal_complete_financials_date
    public.correction_financials_date_basis_enum;

alter table public.client_settings
  add column if not exists reversal_replacement_financials_date
    public.correction_financials_date_basis_enum;

alter table public.client_settings
  add column if not exists healthroster_import_auto_authorise boolean not null default true,
  add column if not exists nhsp_import_auto_authorise boolean not null default false;

alter table public.contracts
  add column if not exists send_ts_queries_to_different_email boolean not null default false,
  add column if not exists ts_queries_alt_email_address text;

alter table public.contracts
  add column if not exists healthroster_import_auto_authorise_override boolean,
  add column if not exists nhsp_import_auto_authorise_override boolean;

alter table public.contracts
  add column if not exists timesheet_break_entry_mode
    public.timesheet_break_entry_mode_enum;

alter table public.timesheets
  add constraint timesheets_candidate_workflow_generation_ck check (
    candidate_workflow_generation is null or candidate_workflow_generation > 0
  ),
  add constraint timesheets_candidate_workflow_pair_ck check (
    (candidate_workflow_id is null and candidate_workflow_generation is null)
    or (candidate_workflow_id is not null and candidate_workflow_generation is not null)
  );

ALTER TABLE public.timesheets
  ADD CONSTRAINT timesheets_candidate_hint_text_is_object
  CHECK (
    candidate_hint_text IS NULL
    OR jsonb_typeof(candidate_hint_text) = 'object'
  );

alter table public.weekly_discrepancy_incidents
  add constraint weekly_discrepancy_incidents_current_comparison_fk
  foreign key (current_comparison_revision_id) references public.weekly_issue_comparison_revisions(id) on delete restrict;

alter table public.weekly_source_billing_movements
  add constraint weekly_source_billing_movements_prior_fk
  foreign key (prior_movement_id) references public.weekly_source_billing_movements(id) on delete restrict;

alter table public.weekly_source_contract_policies
  add constraint weekly_source_contract_policies_no_overlap
  exclude using gist (
    contract_id with =,
    daterange(effective_from,coalesce(effective_to,'infinity'::date),'[]') with &&
  );

alter table public.weekly_source_cycles
  add constraint weekly_source_cycles_current_upload_fk
  foreign key (current_complete_upload_id) references public.weekly_source_uploads(id) on delete restrict;

alter table public.weekly_source_cycles
  add constraint weekly_source_cycles_current_final_fk
  foreign key (current_final_revision_id) references public.weekly_source_final_revisions(id) on delete restrict;

alter table public.weekly_source_cycles
  add constraint weekly_source_cycles_current_publication_fk
  foreign key (current_projection_publication_id) references public.weekly_source_projection_publications(id) on delete restrict;

alter table public.weekly_source_cycles
  add constraint weekly_source_cycles_group_week_client_uq
  unique nulls not distinct (source_group_id,finalisation_week_ending,scope_client_id);

alter table public.weekly_source_final_revisions
  add constraint weekly_source_final_revisions_predecessor_fk
  foreign key (predecessor_revision_id) references public.weekly_source_final_revisions(id) on delete restrict;

alter table public.weekly_source_final_revisions
  add constraint weekly_source_final_revisions_prior_cutoff_fk
  foreign key (prior_state_cutoff_revision_id) references public.weekly_source_final_revisions(id) on delete restrict;

alter table public.weekly_source_group_clients
  add constraint weekly_source_group_clients_no_overlap
  exclude using gist (
    client_id with =,
    daterange(valid_from,coalesce(valid_to,'infinity'::date),'[]') with &&
  );

alter table public.weekly_source_report_scopes
  add constraint weekly_source_report_scopes_current_upload_fk
  foreign key (current_complete_upload_id) references public.weekly_source_uploads(id) on delete restrict;

alter table public.weekly_source_report_scopes
  add constraint weekly_source_report_scopes_current_final_fk
  foreign key (current_final_revision_id) references public.weekly_source_final_revisions(id) on delete restrict;

alter table public.weekly_source_report_scopes
  add constraint weekly_source_report_scopes_current_publication_fk
  foreign key (current_projection_publication_id) references public.weekly_source_projection_publications(id) on delete restrict;

alter table public.weekly_source_report_scopes
  add column self_bill_report_id uuid references public.weekly_source_self_bill_reports(id) on delete restrict,
  drop constraint weekly_source_report_scopes_environment_agency_id_source_gr_key;

alter table public.weekly_source_upload_rows
  drop constraint weekly_source_upload_rows_row_finalisation_state_check,
  add constraint weekly_source_upload_rows_row_finalisation_state_check check (row_finalisation_state in ('NOT_APPLICABLE','SOURCE_WORKED','SOURCE_ABSENT_ZERO','SOURCE_UNFINALISED','BLOCK_FINALISATION_DISAGREEMENT','BLOCK_ACTUAL_TUPLE','SOURCE_REPORT_LINE'));

alter table public.weekly_source_uploads
  drop constraint weekly_source_uploads_coverage_proof_kind_check,
  add constraint weekly_source_uploads_coverage_proof_kind_check check (coverage_proof_kind in ('FORMAT_MANIFEST','OFFICE_COMPLETE_EXPORT_ATTESTATION','EXPLICIT_EMPTY_CONFIRMATION','NHSP_TRUST_REPORT_SCOPE','HEALTHROSTER_COMPLETE_EXPORT_ATTESTATION','SELF_BILL_REPORT_SCOPE'));
